#include <iostream>

int main()
{
    int a{};
    int b{};
    if (!(std::cin >> a >> b)) return 0;

    if (b == 0)
        std::cout << "cannot divide by zero\n";
    else if (a % b == 0)
        std::cout << "divides " << a / b << "\n";
    else
        std::cout << "remainder " << a % b << "\n";

    return 0;
}
